#define MAX_STEPS 120
#define MAX_DIST 60.0
#define SURF_DIST 0.01

float gTime = 0.0;

// Smooth color palette
vec3 palette(float t) {
    return mix(vec3(0.3, 0.1, 0.6), vec3(0.9, 0.7, 0.2), t);
}

// 2D rotation matrix
mat2 rot(float a) {
    float c = cos(a), s = sin(a);
    return mat2(c, s, -s, c);
}

// Signed distance to a sphere
float sdSphere(vec3 p, float r) {
    return length(p) - r;
}

// Floating ring (torus) distance
float sdRing(vec3 p, vec2 t) {
    vec2 q = vec2(length(p.xz) - t.x, p.y);
    return length(q) - t.y;
}

// Spiraling spheres and rings scene
float spiralingScene(vec3 pos) {
    float d = 1e10;

    // Spiral of spheres
    for (int i = 0; i < 10; i++) {
        pos.xy *= rot(gTime * 0.1 + float(i) * 0.05);
        pos.yz *= rot(sin(gTime * 0.3) * 0.2);
        d = min(d, sdSphere(pos - vec3(0.0, sin(iTime * 0.5) * float(i) * 0.3, -float(i) * 2.0), 0.5));
    }

    // Floating rings
    d = min(d, sdRing(pos - vec3(0.0, sin(gTime) * 1.5, 0.0), vec2(1.5, 0.05)));

    return d;
}

// Raymarching
vec4 rayMarch(vec3 ro, vec3 rd) {
    float t = 0.0;
    vec3 col = vec3(0.0);

    for (int i = 0; i < MAX_STEPS; i++) {
        vec3 p = ro + rd * t;
        float d = spiralingScene(p);

        if (d < SURF_DIST || t > MAX_DIST) break;

        float c = length(p) * 0.04;
        col += palette(c) / (10.0 + d * 30.0);
        t += d * 0.5;
    }

    return vec4(col, 1.0 - t * 0.02);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5 * iResolution.xy) / iResolution.y;

    // Camera setup
    vec3 ro = vec3(0.0, 0.0, -10.0);
    vec3 rd = normalize(vec3(uv, 1.0));

    gTime = iTime;
    rd.xy *= rot(sin(iTime * 0.2) * 0.5);

    fragColor = rayMarch(ro, rd);
}
